"""Database access: one SQLAlchemy engine, hand-written SQL everywhere.

SQLAlchemy is used only for connection pooling and named-parameter binding
(``:name`` works on both SQLite and PostgreSQL). There is no ORM; every query
in OpsPilot is plain SQL so it can be read, explained and tuned directly.
"""

from __future__ import annotations

from contextlib import contextmanager
from importlib import resources
from typing import Any

from sqlalchemy import create_engine, event, text
from sqlalchemy.engine import Connection, Engine

_ID_TYPES = {
    "postgresql": "INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY",
    "sqlite": "INTEGER PRIMARY KEY AUTOINCREMENT",
}


def make_engine(url: str) -> Engine:
    if url.startswith("postgres://"):  # Heroku-style URLs
        url = "postgresql://" + url[len("postgres://") :]
    if url.startswith("postgresql://"):
        url = "postgresql+psycopg://" + url[len("postgresql://") :]

    engine = create_engine(url, future=True, pool_pre_ping=True)
    if engine.dialect.name == "sqlite":
        # SQLite ignores foreign keys unless asked, per connection.
        @event.listens_for(engine, "connect")
        def _fk_on(dbapi_conn, _record):  # pragma: no cover - trivial
            cur = dbapi_conn.cursor()
            cur.execute("PRAGMA foreign_keys = ON")
            cur.close()

    return engine


def render_schema(dialect: str) -> str:
    sql = resources.files("opspilot").joinpath("schema.sql").read_text(encoding="utf-8")
    return sql.replace("{{ID}}", _ID_TYPES[dialect])


def init_schema(engine: Engine) -> None:
    ddl = render_schema(engine.dialect.name)
    with engine.begin() as conn:
        for statement in _split_statements(ddl):
            conn.execute(text(statement))


def drop_all(engine: Engine) -> None:
    tables = [
        "suggestion_runbooks",
        "ai_suggestions",
        "incident_events",
        "incidents",
        "runbooks",
        "engineers",
        "services",
        "log_ingests",
    ]
    with engine.begin() as conn:
        for table in tables:
            conn.execute(text(f"DROP TABLE IF EXISTS {table}"))


def _split_statements(sql: str) -> list[str]:
    lines = [ln for ln in sql.splitlines() if not ln.strip().startswith("--")]
    return [s.strip() for s in "\n".join(lines).split(";") if s.strip()]


def seconds_between(dialect: str, start: str, end: str) -> str:
    """SQL expression for the number of seconds from ``start`` to ``end``."""
    if dialect == "postgresql":
        return f"EXTRACT(EPOCH FROM ({end} - {start}))"
    return f"((julianday({end}) - julianday({start})) * 86400.0)"


@contextmanager
def transaction(engine: Engine):
    with engine.begin() as conn:
        yield conn


def fetch_all(conn: Connection, sql: str, **params: Any) -> list[dict]:
    return [dict(row._mapping) for row in conn.execute(text(sql), params)]


def fetch_one(conn: Connection, sql: str, **params: Any) -> dict | None:
    row = conn.execute(text(sql), params).first()
    return dict(row._mapping) if row else None


def insert_returning_id(conn: Connection, sql: str, **params: Any) -> int:
    """Run an INSERT ... RETURNING id (supported by PostgreSQL and SQLite 3.35+)."""
    return int(conn.execute(text(sql + " RETURNING id"), params).scalar_one())
